/* SQL ID : AutoAlimMsgDAO.autoAlimMsgSearchCondition 설 명 : 자동알림메시지 검색 조건 */
AND A.ORG_ID = #{orgId}
AND (A.AUTO_ALIMNM LIKE FN_LIKE_VAL(#{searchText}) OR A.AUTO_ALIM_MSG_CTS LIKE FN_LIKE_VAL(#{searchText}) OR A.SNDNG_CNDTN_CTS LIKE FN_LIKE_VAL(#{searchText}))

mapper.insert:
/*
     SQL ID : AutoAlimMsgDAO.insertAutoAlimMsg
     설  명 : 자동알림메시지 등록
 */
INSERT INTO TB_LMS_AUTO_ALIM_MSG (
      AUTO_ALIM_MSG_ID
    , ORG_ID
    , AUTO_ALIMNM
    , AUTO_ALIM_MSG_CTS
    , SNDNG_CNDTN_CTS
    , RGTR_ID
    , REG_DTTM
) VALUES (
      #{autoAlimMsgId}
    , #{orgId}
    , #{autoAlimnm}
    , #{autoAlimMsgCts}
    , #{sndngCndtnCts}
    , #{rgtrId}
    , FN_DTTM()
)

mapper.update:
/*
     SQL ID : AutoAlimMsgDAO.updateAutoAlimMsg
     설  명 : 자동알림메시지 수정
 */
UPDATE TB_LMS_AUTO_ALIM_MSG
SET AUTO_ALIMNM = #{autoAlimnm}
  , AUTO_ALIM_MSG_CTS = #{autoAlimMsgCts}
  , SNDNG_CNDTN_CTS = #{sndngCndtnCts}
  , ORG_ID = #{orgId}
  , MDFR_ID = #{mdfrId}
  , MOD_DTTM = FN_DTTM()
WHERE AUTO_ALIM_MSG_ID = #{autoAlimMsgId}

mapper.delete:
/*
     SQL ID : AutoAlimMsgDAO.deleteAutoAlimMsg
     설  명 : 자동알림메시지 삭제
 */
DELETE FROM TB_LMS_AUTO_ALIM_MSG
WHERE AUTO_ALIM_MSG_ID = #{autoAlimMsgId}

mapper.insert:
/*
     SQL ID : AutoAlimMsgDAO.insertAutoAlimMsgTrgt
     설  명 : 자동알림메시지 대상 등록
 */
INSERT INTO TB_LMS_AUTO_ALIM_MSG_TRGT (
      AUTO_ALIM_MSG_TRGT_ID
    , AUTO_ALIM_MSG_ID
    , AUTO_ALIM_TRGT_TYCD
    , RGTR_ID
    , REG_DTTM
) VALUES (
      #{autoAlimMsgTrgtId}
    , #{autoAlimMsgId}
    , #{autoAlimTrgtTycd}
    , #{rgtrId}
    , FN_DTTM()
)

mapper.delete:
/*
     SQL ID : AutoAlimMsgDAO.deleteAutoAlimMsgTrgtByMsgId
     설  명 : 자동알림메시지 대상 일괄 삭제
 */
DELETE FROM TB_LMS_AUTO_ALIM_MSG_TRGT
WHERE AUTO_ALIM_MSG_ID = #{autoAlimMsgId}
